import {loadPma} from './pma.mjs';
import {nivel} from './level.mjs';
import {tasksFor,keyFor,installation,quality,fields,reportProgress} from './room-progress-model.mjs';
import {readProgress,saveProgress,exportProgress,importProgress} from './room-progress-store.mjs';
import {workChart} from './work-charts.mjs';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const options=(values,current,esc)=>values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');
const download=value=>{const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Atlas-avance-N-1-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
export async function renderRoomProgress(root,room,esc,afterSave=()=>{}){
 if(nivel.id!=='N-1'){root.textContent='Piloto de avance disponible en el nivel −1.';return;}
 const serial=(Number(root.dataset.progressSerial)||0)+1;root.dataset.progressSerial=serial;root.textContent='Cargando checklist…';
 try{
 const [model,snapshot]=await Promise.all([loadPma(),readProgress()]);if(!root.isConnected||Number(root.dataset.progressSerial)!==serial)return;
 const current=snapshot.records.find(r=>r.key===keyFor(room.code)),version=current?.version||0,tasks=tasksFor(model,room),summary=reportProgress(model,[room],snapshot.records).rows[0],draftKey='atlas-room-draft:'+keyFor(room.code);
 let draft;try{draft=JSON.parse(sessionStorage.getItem(draftKey));}catch{}
 const compatible=draft&&draft.version===version&&draft.sourceSha===model.source.sha256,base=compatible?draft:current;
 root.innerHTML=`<h3>Avance en terreno · Nivel −1</h3><p>${esc(room.code)} · ${esc(room.name)}</p><p class="muted">Guardado en este dispositivo. Cada partida registra instalación y revisión por separado.</p>${summary.warnings.map(w=>`<p class="pmaWarning">${esc(w)}</p>`).join('')}${draft?`<p>${compatible?'Borrador recuperado; aún no guardado.':'Hay un borrador de otra versión. Descárgalo antes de reemplazarlo.'}</p><button type="button" id="downloadRoomDraft">Descargar borrador</button>`:''}<form id="roomProgressForm"><label>Responsable<input name="responsible" required maxlength="200" value="${esc(base?.responsible||'')}"></label><label>Fecha de revisión<input name="date" type="date" required value="${esc(base?.date||today())}"></label>${tasks.map(t=>{const v=base?.fields?.[t.field],same=base?.sourceSha===model.source.sha256&&v?.code===t.code;return `<details class="progressTask" ${t.field==='PAV'?'open':''}><summary>${esc(t.name)} · ${esc(t.code||'Sin código')} · ${esc(same?v.installation:'Sin registrar')}</summary><p>${esc(t.description)}${t.field!=='PAV'?'<br>Asepsia de pintura requerida: '+esc(t.asepsis||'Sin dato'):''}</p>${!t.applicable?'<p>No aplica según PMA; fuera del cálculo.</p>':!t.documented?'<p>Requiere definición documental; fuera del porcentaje y bloquea recinto completo.</p>':`<label>Instalación<select name="${t.field}_installation">${options(installation,same?v.installation:'Sin registrar',esc)}</select></label><label>Condición / revisión<select name="${t.field}_quality">${options(quality,same?v.quality:'Sin revisar',esc)}</select></label><label>Qué falta<textarea name="${t.field}_missing" maxlength="5000">${esc(v?.missing||'')}</textarea></label><label>Observaciones de esta partida<textarea name="${t.field}_notes" maxlength="5000">${esc(v?.notes||'')}</textarea></label>`}</details>`;}).join('')}${!tasks.length?'<p>No hay correspondencia PMA para generar partidas.</p>':''}<label>Observaciones generales del recinto<textarea name="notes" maxlength="10000">${esc(base?.notes||'')}</textarea></label>${summary.warnings.length||current&&current.sourceSha!==model.source.sha256?'<label class="check"><input name="sourceReviewed" type="checkbox" required> Cotejé las diferencias documentales antes de registrar el avance.</label>':''}<p class="progressFeedback" role="status"></p><div class="actions"><button type="submit" ${!tasks.length?'disabled':''}>Guardar avance</button><button type="button" id="discardRoomDraft">Descartar borrador</button></div></form><details><summary>Historial de este recinto</summary>${snapshot.history.filter(h=>h.record.key===keyFor(room.code)).sort((a,b)=>b.record.version-a.record.version).map(h=>`<article><b>Versión ${h.record.version} · ${esc(h.record.date)} · ${esc(h.record.responsible)}</b><p>${esc(h.record.notes)}</p>${Object.entries(h.record.fields).map(([f,v])=>`<p>${esc(fields[f])}: ${esc(v.installation)} · ${esc(v.quality)}<br>Falta: ${esc(v.missing)}<br>${esc(v.notes)}</p>`).join('')}</article>`).join('')||'<p>Sin registros guardados.</p>'}</details>`;
 const form=root.querySelector('form'),feedback=root.querySelector('.progressFeedback');if(draft&&!compatible)form.querySelectorAll('input,select,textarea,button[type=submit]').forEach(e=>e.disabled=true);
 const values=()=>{const f=new FormData(form);return {key:keyFor(room.code),code:room.code,level:'N-1',sourceSha:model.source.sha256,version,responsible:String(f.get('responsible')||''),date:String(f.get('date')||''),sourceReviewed:f.has('sourceReviewed'),notes:String(f.get('notes')||''),fields:Object.fromEntries(tasks.filter(t=>t.applicable&&t.documented).map(t=>[t.field,{code:t.code,installation:f.get(t.field+'_installation'),quality:f.get(t.field+'_quality'),missing:String(f.get(t.field+'_missing')||''),notes:String(f.get(t.field+'_notes')||'')}]))};};
 form.oninput=()=>{try{sessionStorage.setItem(draftKey,JSON.stringify(values()));feedback.textContent='Borrador conservado en esta pestaña. Pulsa Guardar avance para incorporarlo a los gráficos.';}catch{feedback.textContent='No se pudo conservar el borrador. Guarda antes de salir.';}};
 root.querySelector('#downloadRoomDraft')?.addEventListener('click',()=>download({format:'atlas-room-progress-draft',draft}));
 root.querySelector('#discardRoomDraft').onclick=()=>{sessionStorage.removeItem(draftKey);renderRoomProgress(root,room,esc,afterSave);};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const value={...values(),version:version+1,at:new Date().toISOString()};await saveProgress(value,version);sessionStorage.removeItem(draftKey);await renderRoomProgress(root,room,esc,afterSave);if(root.isConnected)root.querySelector('.progressFeedback').textContent='Avance guardado con historial.';afterSave();}catch(error){feedback.textContent=error.message;button.disabled=false;}};
 }catch(error){if(root.isConnected){root.textContent=error.message;const b=document.createElement('button');b.textContent='Reintentar';b.onclick=()=>renderRoomProgress(root,room,esc,afterSave);root.append(b);}}
}
export async function renderProgressControl(root,ctx){
 if(nivel.id!=='N-1'){root.innerHTML='<p>El piloto de avance por recinto está disponible en el nivel −1.</p>';return;}
 root.textContent='Cargando avance del nivel −1…';
 try{const model=await loadPma();let snapshot=await readProgress(),query='',sector='',status='',family='',asepsis='',filtersOpen=false,selected=null;const esc=ctx.esc;
 const refresh=async()=>{snapshot=await readProgress();if(root.isConnected)draw();};
 function draw(){if(!root.isConnected)return;const all=reportProgress(model,ctx.rooms(),snapshot.records);let rows=all.rows.filter(r=>(!sector||r.room.sector===sector)&&(!asepsis||r.tasks.some(t=>t.asepsis===asepsis))&&(!query||[r.room.code,r.room.name].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!status||(status==='complete'?r.complete:status==='observed'?r.tasks.some(t=>t.quality==='Con observaciones'):status==='unregistered'?r.tasks.some(t=>t.installation==='Sin registrar'):!r.complete)));
 const tasks=rows.flatMap(r=>r.tasks).filter(t=>t.documented&&(!family||t.field===family)),installed=tasks.filter(t=>t.installation==='Instalado').length,accepted=tasks.filter(t=>t.installation==='Instalado'&&t.quality==='Conforme').length;
 const items=values=>values.map(([key,n],i)=>({key,n,color:['#8a9eaa','#bc9863','#357d9a','#4c8a6b'][i%4]}));
 root.innerHTML=`<div class="documentaryIntro"><h2>Avance por recinto · Nivel −1</h2><p>Piloto sobre ${all.rows.length} recintos del plano. Registros de este dispositivo; exporta el respaldo para conservarlos o trasladarlos.</p></div><div class="actions"><button id="progressRefresh">Actualizar avance</button><button id="progressExport">Exportar respaldo</button><label class="progressImportLabel">Importar respaldo<input id="progressImport" type="file" accept="application/json,.json"></label></div><details class="progressFilters" ${filtersOpen?'open':''}><summary>Filtrar avance / buscar recinto</summary><div class="pmaFilters"><label>Recinto<input id="progressQuery" type="search" value="${esc(query)}"></label><label>Sector<select id="progressSector"><option value="">Todos</option>${options([...new Set(all.rows.map(r=>r.room.sector))].sort(),sector,esc)}</select></label><label>Partida<select id="progressFamily"><option value="">Todas</option>${Object.entries(fields).map(([f,n])=>`<option value="${f}" ${family===f?'selected':''}>${n}</option>`).join('')}</select></label><label>Recintos<select id="progressStatus">${[['','Todos'],['complete','Completos y conformes'],['pending','Pendientes'],['observed','Con observaciones'],['unregistered','Sin registrar']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Asepsia requerida<select id="progressAsepsis"><option value="">Todas</option>${options([...new Set(all.rows.flatMap(r=>r.tasks.map(t=>t.asepsis)).filter(Boolean))].sort(),asepsis,esc)}</select></label></div></details><p id="progressMessage" role="status"></p><div class="kpiGrid">${[[installed+' / '+tasks.length,'Partidas instaladas'],[accepted+' / '+tasks.length,'Instaladas y conformes'],[rows.filter(r=>r.complete).length+' / '+rows.length,'Recintos completos y conformes'],[tasks.filter(t=>t.quality==='Con observaciones').length,'Partidas con observaciones']].map(([n,label])=>`<article class="kpi"><span>${label}</span><b>${n}</b></article>`).join('')}</div><p>Instalación: ${tasks.length?(100*installed/tasks.length).toFixed(1)+'%':'sin base'} · Conformidad: ${tasks.length?(100*accepted/tasks.length).toFixed(1)+'%':'sin base'}. Cada partida cuenta una vez, sin ponderación por superficie o costo. En proceso no se convierte en un porcentaje arbitrario. ${all.unknown} partidas sin definición documental.</p><div class="chartGrid">${workChart({title:'Instalación de partidas',kind:'pie',items:items(installation.map(s=>[s,tasks.filter(t=>t.installation===s).length])),emptyText:'Sin partidas en este filtro.'},esc)}${workChart({title:'Instaladas pendientes de revisión o corrección',items:items(quality.map(s=>[s,tasks.filter(t=>t.installation==='Instalado'&&t.quality===s).length])),emptyText:'Todavía no hay partidas instaladas en este filtro.'},esc)}<section class="chartCard"><h3>Avance por partida</h3><p>Instaladas / conformes / total aplicable</p>${Object.entries(fields).filter(([f])=>!family||family===f).map(([f,n])=>{const ts=tasks.filter(t=>t.field===f),done=ts.filter(t=>t.installation==='Instalado').length,ok=ts.filter(t=>t.installation==='Instalado'&&t.quality==='Conforme').length;return `<div class="progressFamily"><b>${n}</b><span>${done} / ${ok} / ${ts.length}</span><progress aria-label="${n}: ${done} instaladas de ${ts.length}" value="${done}" max="${ts.length||1}"></progress></div>`;}).join('')}</section>${workChart({title:'Trabajo pendiente por sector',items:items([...new Set(rows.map(r=>r.room.sector))].map(s=>['Sector '+s,rows.filter(r=>r.room.sector===s).flatMap(r=>r.tasks).filter(t=>t.documented&&(!family||t.field===family)&&!(t.installation==='Instalado'&&t.quality==='Conforme')).length]).sort((a,b)=>b[1]-a[1])),subtitle:'Incluye sin registrar, en proceso y partidas que requieren revisión.',emptyText:'Sin pendientes en esta consulta.'},esc)}</div><details class="workRecords" open><summary>Checklist de recintos · ${rows.length}</summary><p>Un recinto completo exige todas sus partidas aplicables instaladas y conformes. La familia filtra partidas; el criterio de recinto completo abarca todas sus terminaciones.</p><div class="progressRoomList">${rows.map(r=>`<button data-progress-room="${esc(r.room.id)}">${esc(r.room.code)} · ${esc(r.room.name)}<small>${r.complete?'Completo y conforme':r.tasks.filter(t=>t.installation==='Instalado').length+'/'+r.tasks.filter(t=>t.documented).length+' partidas instaladas'}${r.warnings.length?' · Diferencias documentales':''}</small></button>`).join('')||'<p>Sin resultados.</p>'}</div></details><section id="progressEditor" class="chartCard" ${selected?'':'hidden'}></section>`;
 for(const [id,key] of [['progressSector','sector'],['progressFamily','family'],['progressStatus','status'],['progressAsepsis','asepsis']])root.querySelector('#'+id).onchange=e=>{if(key==='sector')sector=e.target.value;if(key==='family')family=e.target.value;if(key==='status')status=e.target.value;if(key==='asepsis')asepsis=e.target.value;selected=null;draw();};
 root.querySelector('.progressFilters').ontoggle=e=>{filtersOpen=e.target.open;};
 root.querySelector('#progressQuery').oninput=e=>{query=e.target.value;selected=null;draw();const input=root.querySelector('#progressQuery');input.focus();input.setSelectionRange(query.length,query.length);};
 root.querySelectorAll('[data-progress-room]').forEach(b=>b.onclick=()=>{selected=ctx.rooms().find(r=>r.id===b.dataset.progressRoom);const editor=root.querySelector('#progressEditor');editor.hidden=false;renderRoomProgress(editor,selected,esc,()=>refresh());editor.scrollIntoView({block:'start'});});
 root.querySelector('#progressRefresh').onclick=refresh;
 root.querySelector('#progressExport').onclick=async()=>{try{download(await exportProgress());}catch(e){root.querySelector('#progressMessage').textContent=e.message;}};
 root.querySelector('#progressImport').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('Respaldo demasiado grande');await importProgress(JSON.parse(await f.text()));await refresh();root.querySelector('#progressMessage').textContent='Respaldo importado.';}catch(error){root.querySelector('#progressMessage').textContent=error.message;}};
 if(selected)renderRoomProgress(root.querySelector('#progressEditor'),selected,esc);
 }
 draw();
 }catch(error){if(root.isConnected){root.textContent=error.message;const b=document.createElement('button');b.textContent='Reintentar';b.onclick=()=>renderProgressControl(root,ctx);root.append(b);}}
}
